// Actual Updates modules with local synthetic transport; no backend/persistence.
import React, {useLayoutEffect, useState} from 'react'
import {createRoot} from 'react-dom/client'
import '../../client/src/index.css'
import '../../client/src/App.css'
import {UpdatesPage} from '../../client/src/features/spaces/UpdatesPage'
import {WorkspaceRail} from '../../client/src/features/workspace/components/WorkspaceRail'
import {MobileNavigation} from '../../client/src/features/workspace/components/MobileNavigation'
import {applyAppearancePreference, type AppearancePreference} from '../../client/src/shared/appearance'
import type {SpaceSharedObject} from '../../client/src/features/spaces/types'
const params=new URLSearchParams(location.search),scene=params.get('scene')??'items'
const common={space_id:'project',space_name:'Product planning',chat_id:'general',channel_name:'team-coordination',message_id:'message',response_counts:{},created_by:'me',created_at:'2026-10-04T08:00:00Z'}
const poll={...common,id:'poll',object_type:'poll',title:'Choose the next review time',state:'active',payload:{options:[{id:'a',text:'Tuesday morning'},{id:'b',text:'Wednesday afternoon'}]}}
const checklist={...common,id:'checklist',object_type:'checklist',title:'Prepare the release notes and review the remaining accessibility details with the team',state:'active',payload:{items:[{id:'review',text:'Review the release notes',done:false,assigneeId:'me'},{id:'done',text:'Gather feedback from the team',done:true}]}}
const event={...common,id:'event',object_type:'event',title:'Team review',state:'active',payload:{startsAt:'2026-10-04T08:00:00Z',endsAt:'2026-10-04T09:00:00Z',timezone:'UTC',locationText:'Design room'},my_response:{rsvp:'yes'}}
const decision={...common,id:'decision',object_type:'decision',title:'Release scope agreed',state:'active',payload:{quote:'Ship the reviewed messaging improvements before beginning the next phase.'}}
const closedPoll={...poll,id:'closed-poll',title:'Review time confirmed',state:'closed',response_counts:{a:3,b:1},my_response:{optionIds:['a']}}
let stacks={needsYou:[poll,checklist],happening:[event],decided:[closedPoll,decision]} as {needsYou:SpaceSharedObject[];happening:SpaceSharedObject[];decided:SpaceSharedObject[]}
if(scene==='decided')stacks={needsYou:[],happening:[],decided:[closedPoll,{...checklist,state:'completed',payload:{items:checklist.payload.items.map(i=>({...i,done:true}))}},decision]} as typeof stacks
if(scene==='empty'||scene==='error')stacks={needsYou:[],happening:[],decided:[]}
const calls=scene==='items'?[{id:'call',chat_id:'general',call_type:'video',status:'active',created_at:common.created_at,title:'Planning room',space_id:'project',channel_name:'team-coordination'},{id:'direct',chat_id:'direct',call_type:'audio',status:'ringing',created_at:common.created_at,title:'Alex Chen',space_id:null,channel_name:null}]:[]
const trace:string[]=[]
window.fetch=async(input,options={})=>{const path=String(input),method=options.method??'GET';trace.push(method+' '+path);if(scene==='error')return new Response(JSON.stringify({error:{message:'Unable to load Updates.'}}),{status:500});if(method==='POST'){const data=JSON.parse(String(options.body));if(data.type==='checklist'){const item=stacks.needsYou.find(o=>o.id==='checklist')!;item.payload.items=item.payload.items?.map(i=>i.id===data.itemId?{...i,done:data.done}:i);if(item.payload.items?.every(i=>i.done)){stacks.needsYou=stacks.needsYou.filter(o=>o.id!==item.id);stacks.decided=[{...item,state:'completed'},...stacks.decided]}}if(data.type==='poll'){const item=stacks.needsYou.find(o=>o.id==='poll')!;item.my_response={optionIds:data.optionIds}}if(data.type==='event')stacks.happening[0].my_response={rsvp:data.rsvp};return new Response('{}',{headers:{'Content-Type':'application/json'}})}if(path.startsWith('/api/spaces/updates')){const q=new URL(path,'http://fixture.invalid').searchParams.get('q')?.toLowerCase()??'';const selected=Object.fromEntries(Object.entries(stacks).map(([k,items])=>[k,items.filter(o=>o.title.toLowerCase().includes(q))]));return new Response(JSON.stringify({stacks:selected,activeCalls:calls}),{headers:{'Content-Type':'application/json'}})}throw new Error('Unexpected fixture request '+path)}
const user={id:'me',email:'preview@example.invalid',username:'sam',display_name:'Sam Rivera'}
function Preview(){const [actions,setActions]=useState<string[]>([]);useLayoutEffect(()=>applyAppearancePreference((params.get('theme')??'light') as AppearancePreference),[]);const record=(value:string)=>setActions(a=>[...a,value]);return <><output hidden aria-label="Fixture navigation">{actions.join('\n')}</output><main className="workspace has-active-updates ui:bg-canvas"><WorkspaceRail user={user} showCalls={false} showUpdates showSpaces={false} unreadConversationCount={0} onShowChats={()=>record('chats')} onShowCalls={()=>record('calls')} onShowUpdates={()=>record('updates')} onShowSpaces={()=>record('spaces')} onOpenAccount={()=>record('account')}/><UpdatesPage userId="me" onOpenTarget={(...ids)=>record('target:'+ids.join(':'))} onOpenCall={call=>record('call:'+call.id)}/><MobileNavigation section="updates" accountOpen={false} unreadConversationCount={0} onShowChats={()=>record('chats')} onShowCalls={()=>record('calls')} onShowUpdates={()=>record('updates')} onShowSpaces={()=>record('spaces')} onOpenAccount={()=>record('account')}/><footer className="workspace-footer"><button type="button" onClick={()=>record('signout')}>Sign out</button><span>Chats · End-to-end encrypted</span></footer></main></>}
createRoot(document.getElementById('root')!).render(<Preview/> )
